      "כל שנה, כשמגיע חג החנוכה, המשפחה שלי נפגשת בבית של סבתא שלי בירושלים. אני אוהבת את המסורת הזאת כי היא מזכירה לי את הילדות שלי. בערב הראשון אנחנו מדליקים את הנר הראשון בחנוכייה הישנה של סבא, ואחר כך כולם שרים שירים ביחד. סבתא שלי מטגנת סופגניות וגם לביבות תפוחי אדמה, והריח ממלא את כל הבית. הילדים הקטנים מקבלים דמי חנוכה מהדודים והדודות, ומשחקים בסביבון עד שעה מאוחרת. השנה, למרות שהיינו עייפים מאוד אחרי יום ארוך בעבודה, כולנו הגענו כי חשוב לנו לשמור על המסורת. אחי הקטן סיפר בדיחות מצחיקות וכולם צחקו הרבה. בסוף הערב, לפני שהלכנו הביתה, סבתא נתנה לכל אחד מאיתנו מתנה קטנה. אני מקווה שנמשיך לחגוג ככה גם בעתיד, כי המשפחה היא הדבר הכי חשוב בחיים שלי.",
