      "Каждый год, когда наступает праздник Ханука, моя семья собирается в доме моей бабушки в Иерусалиме. Мне нравится эта традиция, потому что она напоминает мне о моём детстве. В первый вечер мы зажигаем первую свечу в старой ханукии дедушки, а потом все вместе поём песни. Бабушка жарит пончики и картофельные латкес, и запах наполняет весь дом. Маленькие дети получают ханукальные деньги от дядей и тётей и играют в дрейдл допоздна. В этом году, хотя мы были очень уставшими после долгого дня на работе, все приехали, потому что для нас важно сохранять традицию. Мой младший брат рассказывал смешные шутки, и все много смеялись. В конце вечера, перед тем как разойтись по домам, бабушка дала каждому из нас маленький подарок. Я надеюсь, что мы будем праздновать так и в будущем, потому что семья — самое важное в моей жизни.",
