      "לפני שנתיים לא הייתי מסוגלת לרוץ אפילו חמש דקות בלי להתנשף קשה. הרופאה שלי אמרה לי שאני צריכה יותר פעילות גופנית כי לחץ הדם שלי היה גבוה מדי. בהתחלה זה היה מביך מאוד, כי אני זוכרת שרצתי לאט מאוד ברחוב וכל השכנים ראו אותי. למרות הקושי, החלטתי להתמיד ולצאת לריצה שלוש פעמים בשבוע, גם כשהיה קר או גשום. הצטרפתי לקבוצת ריצה בשכונה, וזה עזר לי מאוד כי מצאתי שם חברות חדשות שעודדו אותי להמשיך. אחרי כמה חודשים כבר יכולתי לרוץ עשרים דקות ברצף בלי לעצור, וזה נתן לי המון ביטחון עצמי. השנה, לראשונה בחיים שלי, השתתפתי במרוץ עשרה קילומטרים בעיר שלי וסיימתי אותו בגאווה גדולה. לחץ הדם שלי ירד באופן משמעותי, ואני ישנה טוב יותר בלילה. היום ריצה היא חלק חשוב מהיום שלי, ואני כבר לא מדמיינת את החיים בלעדיה.",
    translation:
      "Два года назад я не могла бежать даже пять минут без сильной одышки. Моя врач сказала мне, что мне нужно больше физической активности, потому что давление у меня было слишком высоким. Сначала было очень неловко — я помню, как бежала очень медленно по улице, и все соседи видели меня. Несмотря на трудности, я решила не сдаваться и выходить на пробежку три раза в неделю, даже когда было холодно или дождливо. Я присоединилась к беговой группе в районе, и это очень помогло, потому что там я нашла новых подруг, которые поддерживали меня. Через несколько месяцев я уже могла бежать двадцать минут без остановки, и это дало мне огромную уверенность в себе. В этом году я впервые в жизни участвовала в забеге на десять километров в своём городе и завершила его с большой гордостью. Моё давление значительно снизилось, и я лучше сплю по ночам. Сегодня бег — важная часть моего дня, и я уже не представляю без него жизнь.",
