    translation:
      "Год назад я присоединился к любительскому хору в своём районе, хотя никогда раньше не пел на публике. Сначала я очень боялся сцены и опасался, что мой голос недостаточно хорош, но дирижёр подбадривал меня продолжать. Мы репетировали дважды в неделю на протяжении долгих месяцев, учили песни на иврите, русском и английском и готовили специальную программу для большого концерта. За неделю до выступления я чуть не бросил всё от стресса, потому что боялся забыть слова перед большой публикой. Друзья по хору помогли мне успокоиться и сказали, что все мы чувствуем один и тот же страх. В сам вечер выступления, когда я поднялся на сцену в местном доме культуры, я увидел, что моя семья сидит в первом ряду и улыбается мне. Мы спели три песни, и когда публика встала и зааплодировала в конце, я почувствовал гордость, какой никогда прежде не испытывал. После выступления мы все вместе пошли отмечать в маленьком ресторане до глубокой ночи. С тех пор я продолжаю петь в хоре каждую неделю, и это стало самой волнующей частью моей недели.",
