    translation:
      "Когда мы купили квартиру год назад, мы знали, что старая кухня нуждается в капитальном ремонте, потому что шкафы были сломаны, а трубы очень старые. Сначала мы думали сделать всё сами, чтобы сэкономить деньги, но через неделю поняли, что нам нужен профессиональный подрядчик. Мы искали рекомендации у друзей и семьи и в итоге нашли надёжного подрядчика, предложившего справедливую цену. Ремонт длился почти три месяца, и всё это время мы готовили только на маленькой электрической плитке в гостиной. Было много неприятных сюрпризов, например повреждённая труба, которую мы обнаружили только после того, как разобрали стены. Несмотря на трудности и расходы, превысившие наш первоначальный бюджет, мы решили не идти на компромисс в качестве работы. В конце процесса мы получили современную красивую кухню с новыми шкафами и белой мраморной столешницей. Когда я увидела итоговый результат, я сразу забыла обо всех тяжёлых месяцах и разочаровании. Сегодня, каждый раз готовя на новой кухне, я чувствую огромную гордость за наше решение.",
