      "לפני שנה הרופאה שלי אמרה לי שרמת הסוכר בדם שלי גבוהה מדי ושאני צריכה לשנות את התזונה שלי באופן משמעותי. בהתחלה זה היה קשה מאוד, כי אהבתי לאכול הרבה ממתקים ומזון מהיר כמעט כל יום. הפסקתי לקנות חטיפים ומשקאות ממותקים, והתחלתי לבשל בבית ארוחות בריאות עם ירקות טריים וחלבון רזה. בכל שבוע תכננתי מראש את התפריט שלי, וזה עזר לי מאוד להימנע מפיתויים בסופר. בהתחלה החברים שלי צחקו קצת כשסירבתי לעוגה במסיבות, אבל עם הזמן הם התחילו לכבד את ההחלטה שלי. למרות שלפעמים התגעגעתי מאוד לשוקולד ולעוגות, הזכרתי לעצמי כמה חשוב הבריאות שלי לטווח ארוך. אחרי שלושה חודשים ראיתי שיפור ברור בבדיקות הדם, ורמת הסוכר שלי חזרה כמעט לנורמה. גם ירדתי במשקל וישנתי טוב יותר בלילה, וזה נתן לי אנרגיה רבה יותר ביום. היום, שנה אחרי השינוי הגדול הזה, אני מרגישה שהתזונה הבריאה הפכה להרגל טבעי ולא למאמץ.",
    translation:
      "Год назад моя врач сказала мне, что уровень сахара в крови у меня слишком высокий и что мне нужно существенно изменить питание. Сначала это было очень тяжело, потому что я любила есть много сладостей и фастфуда почти каждый день. Я перестала покупать снеки и сладкие напитки и начала готовить дома здоровую еду со свежими овощами и постным белком. Каждую неделю я заранее планировала своё меню, и это очень помогало избегать соблазнов в супермаркете. Сначала друзья немного смеялись, когда я отказывалась от торта на вечеринках, но со временем они стали уважать моё решение. Хотя иногда я очень скучала по шоколаду и тортам, я напоминала себе, насколько важно моё здоровье в долгосрочной перспективе. Через три месяца я увидела явное улучшение в анализах крови, и уровень сахара почти вернулся к норме. Я также похудела и стала лучше спать по ночам, и это дало мне гораздо больше энергии в течение дня. Сегодня, спустя год после этой большой перемены, я чувствую, что здоровое питание стало естественной привычкой, а не усилием.",
